CREATE TABLE account_passkeys ( id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, credential TEXT NOT NULL, name TEXT NOT NULL, created_at INTEGER NOT NULL );
CREATE TABLE authenticator_apps ( user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, secret TEXT NOT NULL, created_at INTEGER NOT NULL, last_counter INTEGER NOT NULL DEFAULT -1 );
CREATE TABLE "collection_schedules" ( id TEXT PRIMARY KEY, name TEXT NOT NULL, collection TEXT NOT NULL, cadence TEXT NOT NULL CHECK(cadence IN ('interval','daily')), interval_minutes INTEGER, local_time TEXT NOT NULL, anchor INTEGER NOT NULL, enabled INTEGER NOT NULL CHECK(enabled IN (0,1)), next_run TEXT, revision INTEGER NOT NULL DEFAULT 1, last_error TEXT, created_at TEXT NOT NULL , days INTEGER NOT NULL DEFAULT 127 CHECK (days BETWEEN 1 AND 127), times TEXT CHECK (times IS NULL OR json_valid(times)), until_time TEXT, position INTEGER NOT NULL DEFAULT 0);
CREATE TABLE communications_blocked ( number TEXT PRIMARY KEY, blocked_by TEXT NOT NULL, blocked_at INTEGER NOT NULL );
CREATE TABLE communications_changes ( revision INTEGER PRIMARY KEY, conversation_id TEXT NOT NULL );
CREATE TABLE communications_contacts ( number TEXT PRIMARY KEY, name TEXT NOT NULL, saved_by TEXT NOT NULL, saved_at INTEGER NOT NULL );
CREATE TABLE communications_conversations ( id TEXT PRIMARY KEY, team_id TEXT NOT NULL, user_id TEXT NOT NULL, channel_id TEXT NOT NULL, name TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'responded' CHECK (state IN ('waiting', 'responded', 'done')), waiting_since INTEGER, last_at INTEGER, done_at INTEGER, done_by TEXT, caught_up_at INTEGER, catching_up_to INTEGER, catching_up_before TEXT, group_id TEXT, UNIQUE (team_id, user_id) );
CREATE TABLE communications_deliveries ( message_id TEXT NOT NULL REFERENCES communications_group_messages (id), team_id TEXT NOT NULL, user_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'waiting' CHECK (status IN ('waiting', 'sent', 'failed')), delivered_id TEXT REFERENCES communications_messages (id), due_at INTEGER NOT NULL, claimed_until INTEGER, posting_since INTEGER, attempts INTEGER NOT NULL DEFAULT 0, reason TEXT, PRIMARY KEY (message_id, team_id, user_id) );
CREATE TABLE communications_files ( id TEXT PRIMARY KEY, message_id TEXT REFERENCES communications_messages (id), slack_file_id TEXT, uploaded_by TEXT, name TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL, status TEXT NOT NULL CHECK (status IN ('waiting', 'kept', 'too_large', 'unavailable', 'failed')), sha256 TEXT, added_at INTEGER NOT NULL, due_at INTEGER, claimed_until INTEGER, attempts INTEGER NOT NULL DEFAULT 0, reason TEXT , group_message_id TEXT);
CREATE TABLE communications_group_messages ( id TEXT PRIMARY KEY, group_id TEXT NOT NULL REFERENCES communications_groups (id), text TEXT NOT NULL, sent_by TEXT NOT NULL, sender_name TEXT NOT NULL, sender_initials TEXT, at INTEGER NOT NULL );
CREATE TABLE communications_group_people ( group_id TEXT NOT NULL REFERENCES communications_groups (id), team_id TEXT NOT NULL, user_id TEXT NOT NULL, name TEXT NOT NULL, place INTEGER NOT NULL, PRIMARY KEY (group_id, team_id, user_id) );
CREATE TABLE communications_group_uploads ( message_id TEXT NOT NULL REFERENCES communications_group_messages (id), team_id TEXT NOT NULL, file_id TEXT NOT NULL REFERENCES communications_files (id), slack_file_id TEXT NOT NULL, PRIMARY KEY (message_id, team_id, file_id) );
CREATE TABLE communications_groups ( id TEXT PRIMARY KEY, name TEXT NOT NULL, created_by TEXT NOT NULL, created_at INTEGER NOT NULL, state TEXT NOT NULL DEFAULT 'responded' CHECK (state IN ('waiting', 'responded')), waiting_since INTEGER, last_at INTEGER NOT NULL );
CREATE TABLE communications_messages ( id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES communications_conversations (id), ts TEXT NOT NULL, thread_ts TEXT, direction TEXT NOT NULL CHECK (direction IN ('in', 'out')), sent_by TEXT, sender_name TEXT, text TEXT NOT NULL, at INTEGER NOT NULL, edited_at INTEGER, group_id TEXT, UNIQUE (conversation_id, ts) );
CREATE TABLE communications_picked ( phone TEXT NOT NULL, day TEXT NOT NULL, source TEXT NOT NULL, driver_id TEXT NOT NULL, picked_by TEXT NOT NULL, picked_at INTEGER NOT NULL, PRIMARY KEY (phone, day) );
CREATE TABLE communications_text_conversations ( id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK (kind IN ('work', 'number')), source TEXT, driver_id TEXT, number TEXT, state TEXT NOT NULL DEFAULT 'responded' CHECK (state IN ('waiting', 'responded', 'done')), waiting_since INTEGER, last_at INTEGER, done_at INTEGER, done_by TEXT );
CREATE TABLE communications_texting ( id INTEGER PRIMARY KEY CHECK (id = 1), read_to INTEGER NOT NULL );
CREATE TABLE communications_texts ( id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES communications_text_conversations (id), phone TEXT NOT NULL, direction TEXT NOT NULL CHECK (direction IN ('in', 'out')), number TEXT NOT NULL, body TEXT NOT NULL, at INTEGER NOT NULL, sent_by TEXT, sender_name TEXT, status TEXT CHECK (status IN ('waiting', 'sent', 'delivered', 'failed')), error TEXT, files TEXT NOT NULL DEFAULT '[]', blocked INTEGER NOT NULL DEFAULT 0 , done_at INTEGER, done_by TEXT);
CREATE TABLE documents_connect_requests ( state_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL, verifier TEXT NOT NULL, expires_at INTEGER NOT NULL );
CREATE TABLE documents_connection ( id INTEGER PRIMARY KEY CHECK (id = 1), status TEXT NOT NULL CHECK (status IN ('connected', 'broken')), account_email TEXT NOT NULL, account_kind TEXT NOT NULL CHECK (account_kind IN ('workspace', 'personal')), folder_id TEXT NOT NULL, folder_name TEXT NOT NULL, connected_by TEXT NOT NULL, connected_at TEXT NOT NULL, broken_at TEXT , full_access INTEGER NOT NULL DEFAULT 0);
CREATE TABLE documents_files ( file_id TEXT PRIMARY KEY, added_by TEXT NOT NULL, added_at TEXT NOT NULL, changed_by TEXT NOT NULL, changed_at TEXT NOT NULL , added_name TEXT, changed_name TEXT);
CREATE TABLE documents_people ( user_id TEXT PRIMARY KEY, linked_email TEXT, shared_email TEXT, share_id TEXT, state TEXT NOT NULL CHECK (state IN ('shared', 'needs_account', 'refused')), refusal TEXT, emailed_at TEXT, updated_at TEXT NOT NULL );
CREATE TABLE documents_shared_files ( file_id TEXT NOT NULL, email TEXT NOT NULL, share_id TEXT NOT NULL, shared_at TEXT NOT NULL, PRIMARY KEY (file_id, email) );
CREATE TABLE invitations ( hash TEXT PRIMARY KEY, dsp_id TEXT NOT NULL, email TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','manager','member')), expires_at INTEGER NOT NULL, created_by TEXT NOT NULL, used_at INTEGER, role_id TEXT );
CREATE TABLE memberships ( id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), dsp_id TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','manager','member')), role_id TEXT REFERENCES roles(id), UNIQUE(user_id,dsp_id) );
CREATE TABLE owner_migrations (owner TEXT NOT NULL, id INTEGER NOT NULL, name TEXT NOT NULL, applied_at INTEGER NOT NULL, PRIMARY KEY(owner, id));
CREATE TABLE people ( code TEXT PRIMARY KEY, created_at TEXT NOT NULL, merged_into TEXT REFERENCES people(code), merged_at TEXT, merged_by TEXT, split_from TEXT REFERENCES people(code), created_by TEXT );
CREATE TABLE people_apart ( first TEXT NOT NULL REFERENCES people(code), second TEXT NOT NULL REFERENCES people(code), decided_at TEXT NOT NULL, actor_id TEXT, PRIMARY KEY(first, second), CHECK(first < second) );
CREATE TABLE "person_ids" ( source TEXT NOT NULL, external_id TEXT NOT NULL, code TEXT NOT NULL REFERENCES people(code), linked_by TEXT NOT NULL, linked_at TEXT NOT NULL, actor_id TEXT, PRIMARY KEY(source, external_id) );
CREATE TABLE person_roles ( code TEXT PRIMARY KEY REFERENCES people(code), role TEXT NOT NULL, decided_at TEXT NOT NULL, actor_id TEXT );
CREATE TABLE person_titles ( code TEXT PRIMARY KEY REFERENCES people(code), title TEXT NOT NULL, decided_at TEXT NOT NULL, actor_id TEXT );
CREATE TABLE phones_change ( id INTEGER PRIMARY KEY CHECK (id = 1), last INTEGER NOT NULL );
CREATE TABLE phones_devices ( id TEXT PRIMARY KEY, name TEXT NOT NULL, number TEXT NOT NULL, model TEXT NOT NULL, app_version TEXT NOT NULL, key_sha256 TEXT NOT NULL UNIQUE, paired_at INTEGER NOT NULL, paired_by TEXT NOT NULL, last_seen_at INTEGER, removed_at INTEGER, stand_in INTEGER NOT NULL DEFAULT 0 CHECK (stand_in IN (0, 1)) );
CREATE TABLE phones_files ( id TEXT PRIMARY KEY, text_id TEXT REFERENCES phones_texts (id), added_by TEXT, name TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL, sha256 TEXT, added_at INTEGER NOT NULL );
CREATE TABLE phones_pairings ( code_sha256 TEXT PRIMARY KEY, created_by TEXT NOT NULL, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, used_at INTEGER, device_id TEXT REFERENCES phones_devices (id) , id TEXT, replaced_at INTEGER);
CREATE TABLE phones_texts ( id TEXT PRIMARY KEY, device_id TEXT NOT NULL REFERENCES phones_devices (id), client_id TEXT, direction TEXT NOT NULL CHECK (direction IN ('in', 'out')), origin TEXT NOT NULL CHECK (origin IN ('phone', 'dispatch')), number TEXT NOT NULL, body TEXT NOT NULL, at INTEGER NOT NULL, sent_by TEXT, status TEXT CHECK (status IN ('waiting', 'sent', 'delivered', 'failed')), status_at INTEGER, error TEXT, attempt INTEGER, change INTEGER NOT NULL, conversation_id TEXT REFERENCES communications_text_conversations (id), sender_name TEXT, blocked INTEGER NOT NULL DEFAULT 0, done_at INTEGER, done_by TEXT, UNIQUE (device_id, client_id) );
CREATE TABLE recovery_codes ( hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE );
CREATE TABLE resets ( hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), user_version INTEGER NOT NULL, expires_at INTEGER NOT NULL, used_at INTEGER );
CREATE TABLE roles ( id TEXT PRIMARY KEY, dsp_id TEXT NOT NULL, name TEXT NOT NULL COLLATE NOCASE, permissions TEXT NOT NULL DEFAULT '[]', system INTEGER NOT NULL DEFAULT 0 CHECK(system IN (0,1)), created_at TEXT NOT NULL, UNIQUE(dsp_id,name) );
CREATE TABLE schema_migrations (id INTEGER PRIMARY KEY, name TEXT NOT NULL, applied_at INTEGER NOT NULL);
CREATE TABLE security_challenges ( session_hash TEXT PRIMARY KEY REFERENCES sessions(hash) ON DELETE CASCADE, kind TEXT NOT NULL, state TEXT NOT NULL, expires_at INTEGER NOT NULL );
CREATE TABLE session_metadata ( session_hash TEXT PRIMARY KEY REFERENCES sessions(hash) ON DELETE CASCADE, device TEXT NOT NULL );
CREATE TABLE session_security ( session_hash TEXT PRIMARY KEY REFERENCES sessions(hash) ON DELETE CASCADE, verified_at INTEGER NOT NULL DEFAULT 0, password_verified_at INTEGER NOT NULL DEFAULT 0 );
CREATE TABLE sessions ( hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), user_version INTEGER NOT NULL, expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL );
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE slack_canvas_links ( team_id TEXT NOT NULL, channel_id TEXT NOT NULL, channel_name TEXT NOT NULL, private INTEGER NOT NULL CHECK (private IN (0, 1)), folder_id TEXT NOT NULL, folder_name TEXT NOT NULL, linked_by TEXT NOT NULL, linked_at INTEGER NOT NULL, PRIMARY KEY (team_id, channel_id) );
CREATE TABLE slack_canvas_picks ( team_id TEXT NOT NULL, canvas_id TEXT NOT NULL, title TEXT NOT NULL, channel_id TEXT NOT NULL, channel_name TEXT NOT NULL, private INTEGER NOT NULL CHECK (private IN (0, 1)), folder_id TEXT NOT NULL, folder_name TEXT NOT NULL, picked_by TEXT NOT NULL, picked_at INTEGER NOT NULL, PRIMARY KEY (team_id, canvas_id) );
CREATE TABLE slack_canvases ( team_id TEXT NOT NULL, canvas_id TEXT NOT NULL, channel_id TEXT NOT NULL, title TEXT, status TEXT NOT NULL CHECK (status IN ('waiting', 'synced', 'gone', 'failed')), reason TEXT, attempts INTEGER NOT NULL DEFAULT 0, due_at INTEGER NOT NULL, waiting_since INTEGER, heard_at INTEGER, claimed_at INTEGER, claimed_until INTEGER, edited_at INTEGER, written_edit INTEGER, tried_edit INTEGER, doc_id TEXT, doc_link TEXT, noticed_at INTEGER NOT NULL, synced_at INTEGER, PRIMARY KEY (team_id, canvas_id) );
CREATE TABLE slack_connect_requests ( state_hash TEXT PRIMARY KEY, user_id TEXT, link_hash TEXT, expires_at INTEGER NOT NULL, team_id TEXT, label TEXT, page TEXT, CHECK ((user_id IS NULL) <> (link_hash IS NULL)) );
CREATE TABLE slack_import_links ( team_id TEXT NOT NULL, channel_id TEXT NOT NULL, channel_name TEXT NOT NULL, private INTEGER NOT NULL CHECK (private IN (0, 1)), folder_id TEXT NOT NULL, folder_name TEXT NOT NULL, linked_by TEXT NOT NULL, linked_at INTEGER NOT NULL, PRIMARY KEY (team_id, channel_id) );
CREATE TABLE slack_imports ( team_id TEXT NOT NULL, file_id TEXT NOT NULL, channel_id TEXT NOT NULL, name TEXT, mime TEXT, size INTEGER, posted_by TEXT, posted_name TEXT, status TEXT NOT NULL CHECK (status IN ('waiting', 'saved', 'too_large', 'skipped', 'gone', 'failed')), reason TEXT, attempts INTEGER NOT NULL DEFAULT 0, due_at INTEGER NOT NULL, saved_id TEXT, saved_link TEXT, noticed_at INTEGER NOT NULL, done_at INTEGER, PRIMARY KEY (team_id, file_id) );
CREATE TABLE "slack_install_links" ( link_hash TEXT PRIMARY KEY, team_id TEXT, created_by TEXT NOT NULL, created_at TEXT NOT NULL, expires_at INTEGER NOT NULL, label TEXT );
CREATE TABLE slack_integrations ( team_id TEXT NOT NULL, integration TEXT NOT NULL, turned_on_by TEXT NOT NULL, turned_on_at TEXT NOT NULL, PRIMARY KEY (team_id, integration) );
CREATE TABLE slack_integrations_off ( team_id TEXT NOT NULL, integration TEXT NOT NULL, turned_off_by TEXT NOT NULL, turned_off_at TEXT NOT NULL, PRIMARY KEY (team_id, integration) );
CREATE TABLE slack_logos ( team_id TEXT PRIMARY KEY, source TEXT NOT NULL, version TEXT NOT NULL, picture BLOB NOT NULL );
CREATE TABLE slack_members ( team_id TEXT NOT NULL, user_id TEXT NOT NULL, name TEXT NOT NULL, display_name TEXT, email TEXT, phone TEXT, active INTEGER NOT NULL CHECK (active IN (0, 1)), guest INTEGER NOT NULL CHECK (guest IN (0, 1)), PRIMARY KEY (team_id, user_id) );
CREATE TABLE slack_workspaces ( team_id TEXT PRIMARY KEY, name TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('connected', 'broken')), scopes TEXT NOT NULL, bot_user_id TEXT NOT NULL, app_id TEXT NOT NULL, connected_by TEXT, connected_at TEXT NOT NULL, broken_at TEXT , label TEXT, added_at TEXT);
CREATE TABLE storage_identity ( dsp_id TEXT PRIMARY KEY, provider TEXT NOT NULL, source TEXT NOT NULL );
CREATE TABLE uniform_events ( revision INTEGER PRIMARY KEY, kind TEXT NOT NULL CHECK (kind IN ('initialized', 'created', 'updated', 'archived', 'adjusted')), uniform_id TEXT, uniform_name TEXT NOT NULL, variant_id TEXT, fit TEXT, size TEXT, delta INTEGER, quantity INTEGER, actor_id TEXT NOT NULL, actor_name TEXT NOT NULL, request_id TEXT UNIQUE, at TEXT NOT NULL );
CREATE TABLE uniform_inventory ( id INTEGER PRIMARY KEY CHECK (id = 1), revision INTEGER NOT NULL DEFAULT 0 );
CREATE TABLE uniform_variants ( id TEXT PRIMARY KEY, uniform_id TEXT NOT NULL REFERENCES uniforms(id), fit TEXT NOT NULL CHECK (fit IN ('men', 'women', 'unisex')), size TEXT NOT NULL, quantity INTEGER NOT NULL DEFAULT 0 CHECK (quantity BETWEEN 0 AND 1000000), revision INTEGER NOT NULL, position INTEGER NOT NULL, archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1)) );
CREATE TABLE uniforms ( id TEXT PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL, revision INTEGER NOT NULL, position INTEGER NOT NULL, archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1)) );
CREATE TABLE users ( id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, first_name TEXT NOT NULL, last_name TEXT NOT NULL, password TEXT NOT NULL, platform_owner INTEGER NOT NULL DEFAULT 0 CHECK(platform_owner=0), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','disabled')), version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL );
CREATE INDEX account_passkeys_user ON account_passkeys(user_id);
CREATE INDEX communications_conversations_channels ON communications_conversations (team_id, channel_id);
CREATE INDEX communications_conversations_groups ON communications_conversations (group_id, state);
CREATE INDEX communications_conversations_latest ON communications_conversations (last_at, id);
CREATE INDEX communications_deliveries_due ON communications_deliveries (status, due_at);
CREATE INDEX communications_files_due ON communications_files (status, due_at);
CREATE INDEX communications_files_group_messages ON communications_files (group_message_id);
CREATE INDEX communications_files_message ON communications_files (message_id);
CREATE INDEX communications_group_messages_latest ON communications_group_messages (group_id, at);
CREATE INDEX communications_group_people_members ON communications_group_people (team_id, user_id);
CREATE INDEX communications_groups_latest ON communications_groups (last_at, id);
CREATE INDEX communications_messages_groups ON communications_messages (group_id, at);
CREATE INDEX communications_messages_latest ON communications_messages (conversation_id, at);
CREATE UNIQUE INDEX communications_text_conversations_drivers ON communications_text_conversations (source, driver_id) WHERE driver_id IS NOT NULL;
CREATE INDEX communications_text_conversations_latest ON communications_text_conversations (kind, last_at, id);
CREATE UNIQUE INDEX communications_text_conversations_numbers ON communications_text_conversations (kind, number) WHERE driver_id IS NULL;
CREATE INDEX communications_texts_latest ON communications_texts (conversation_id, at, id);
CREATE INDEX communications_texts_written ON communications_texts (at);
CREATE INDEX invitations_dsp_owner ON invitations(dsp_id,role,expires_at DESC) WHERE used_at IS NULL;
CREATE INDEX invitations_expiry ON invitations(expires_at);
CREATE INDEX invitations_role ON invitations(role_id) WHERE used_at IS NULL;
CREATE INDEX memberships_dsp_role ON memberships(dsp_id,role,user_id);
CREATE INDEX memberships_role ON memberships(role_id);
CREATE INDEX person_ids_code ON person_ids(code);
CREATE INDEX phones_files_text ON phones_files (text_id);
CREATE UNIQUE INDEX phones_pairings_id ON phones_pairings (id);
CREATE INDEX phones_texts_change ON phones_texts (change);
CREATE INDEX phones_texts_filed ON phones_texts (conversation_id, at, id);
CREATE INDEX phones_texts_number ON phones_texts (number, at);
CREATE INDEX phones_texts_waiting ON phones_texts (device_id, status);
CREATE INDEX phones_texts_written ON phones_texts (at);
CREATE INDEX recovery_codes_user ON recovery_codes(user_id);
CREATE INDEX resets_expiry ON resets(expires_at);
CREATE UNIQUE INDEX roles_owner ON roles(dsp_id) WHERE system=1;
CREATE INDEX session_expiry ON sessions(expires_at);
CREATE INDEX slack_canvases_due ON slack_canvases (status, due_at);
CREATE INDEX slack_imports_due ON slack_imports (status, due_at);
CREATE INDEX slack_imports_recent ON slack_imports (team_id, noticed_at);
CREATE UNIQUE INDEX slack_install_links_for ON slack_install_links(ifnull(team_id, ''));
CREATE UNIQUE INDEX uniform_variants_size ON uniform_variants (uniform_id, fit, size COLLATE NOCASE) WHERE archived = 0;
CREATE INDEX uniform_variants_uniform ON uniform_variants (uniform_id, archived, position);
CREATE UNIQUE INDEX uniforms_name ON uniforms (name COLLATE NOCASE) WHERE archived = 0;
